function billing_json(int $status, array $payload): void { http_response_code($status); echo json_encode($payload, JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE); exit; }
function billing_body(): array { $raw=file_get_contents('php://input'); if (!is_string($raw)||strlen($raw)>32768) billing_json(413,['error'=>'Request body is too large.']); $data=json_decode($raw,true); return is_array($data)?$data:[]; }
function billing_same_origin(): void { $origin=(string)($_SERVER['HTTP_ORIGIN']??''); if ($origin==='') return; $https=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||strtolower((string)($_SERVER['HTTP_X_FORWARDED_PROTO']??''))==='https';$expected=($https?'https':'http').'://'.($_SERVER['HTTP_HOST']??''); if(!hash_equals($expected,$origin)) billing_json(403,['error'=>'Cross-origin request rejected.']); }
function billing_csrf(): void { billing_same_origin(); $t=$_SERVER['HTTP_X_CSRF_TOKEN']??null; if(!akh_csrf_verify(is_string($t)?$t:null)) billing_json(403,['error'=>'Session security token expired. Refresh the page and try again.']); }
function billing_admin(): string { $isBilling=(isset($_SESSION['akh_billing_user'])&&is_string($_SESSION['akh_billing_user'])); $u=$isBilling?$_SESSION['akh_billing_user']:akh_admin_current(); if($u===null||$u==='') billing_json(401,['error'=>'Sign in required.']); $db=billing_pdo(); $s=$db->prepare("SELECT username,role FROM users WHERE LOWER(username)=LOWER(?) AND role IN ('admin','accountant') LIMIT 1"); $s->execute([$u]); $row=$s->fetch(PDO::FETCH_ASSOC); if(!$row){if($isBilling)unset($_SESSION['akh_billing_user']);else akh_admin_logout();unset($_SESSION['akh_billing_role']);billing_json(401,['error'=>'This billing account is no longer active.']);} $role=(string)$row['role']; if(($role==='accountant'&&!$isBilling)||($role==='admin'&&$isBilling)||(!isset($_SESSION['akh_billing_role'])&&$role!=='admin')||(isset($_SESSION['akh_billing_role'])&&!hash_equals((string)$_SESSION['akh_billing_role'],$role))){if($isBilling)unset($_SESSION['akh_billing_user']);else akh_admin_logout();unset($_SESSION['akh_billing_role']);billing_json(401,['error'=>'This billing account is no longer active.']);} $_SESSION['akh_billing_role']=$role; return (string)$row['username']; }
function billing_pdo(): PDO { $db=function_exists('akh_db')?akh_db():null; if(!$db instanceof PDO) billing_json(503,['error'=>'Billing database is not configured. Configure MariaDB and apply the billing schema.']); return $db; }
function billing_n8n_auth(): void { $secret=defined('AKH_BILLING_N8N_TOKEN')?(string)AKH_BILLING_N8N_TOKEN:(string)(getenv('AKH_BILLING_N8N_TOKEN')?:''); $h=(string)($_SERVER['HTTP_AUTHORIZATION']??$_SERVER['REDIRECT_HTTP_AUTHORIZATION']??''); $provided=preg_match('/^Bearer\s+(.+)$/i',$h,$m)?trim($m[1]):''; if($secret===''||$provided===''||!hash_equals($secret,$provided)) billing_json(401,['error'=>'Invalid n8n credentials.']); }
function billing_audit(PDO $db,int $id,string $actor,string $action,array $details): void { $s=$db->prepare('INSERT INTO billing_audit_log (billing_id, actor, action, details) VALUES (?, ?, ?, ?)'); $s->execute([$id,$actor,$action,json_encode($details,JSON_UNESCAPED_SLASHES)]); }
$action=(string)($_GET['action']??''); $method=strtoupper((string)($_SERVER['REQUEST_METHOD']??'GET'));
if($action==='login'&&$method==='POST'){billing_csrf();$b=billing_body();$u=trim((string)($b['username']??''));$p=(string)($b['password']??'');if($u===''||strlen($u)>100||$p===''||strlen($p)>200)billing_json(400,['error'=>'Enter username and password.']);$tries=(array)($_SESSION['akh_billing_login_attempts']??[]);$tries=array_values(array_filter($tries,static fn($t)=>is_int($t)&&$t>time()-900));if(count($tries)>=10)billing_json(429,['error'=>'Too many sign-in attempts. Try again later.']);$roleReady=akh_billing_role_schema_ensure();$db=billing_pdo();$roleClause=$roleReady?"role IN ('admin','accountant')":"role='admin'";$s=$db->prepare("SELECT username,password_hash,role FROM users WHERE LOWER(username)=LOWER(?) AND ".$roleClause." LIMIT 1");$s->execute([$u]);$account=$s->fetch(PDO::FETCH_ASSOC);if(!$account||!password_verify($p,(string)$account['password_hash'])){$tries[]=time();$_SESSION['akh_billing_login_attempts']=$tries;billing_json(401,['error'=>'Invalid accountant username or password.']);}session_regenerate_id(true);if((string)$account['role']==='accountant'){akh_admin_logout();$_SESSION['akh_billing_user']=strtolower((string)$account['username']);}else{unset($_SESSION['akh_billing_user']);$_SESSION['akh_admin_user']=strtolower((string)$account['username']);}$_SESSION['akh_billing_role']=(string)$account['role'];unset($_SESSION['akh_billing_login_attempts']);billing_json(200,['user'=>['username'=>(string)$account['username'],'role'=>(string)$account['role']]]);}
if($action==='logout'&&$method==='POST'){billing_csrf();if(isset($_SESSION['akh_billing_user']))unset($_SESSION['akh_billing_user']);else akh_admin_logout();unset($_SESSION['akh_billing_role']);billing_json(200,['ok'=>true]);}
if($action==='me'&&$method==='GET')billing_json(200,['user'=>['username'=>billing_admin(),'role'=>(string)($_SESSION['akh_billing_role']??'admin')],'mode'=>'mariadb']);
if(str_starts_with($action,'n8n-')){
 billing_n8n_auth();$db=billing_pdo();
 if($action==='n8n-eligible'&&$method==='GET'){$s=$db->query("SELECT id,task_code,drive_file_id,file_name,phone,customer_name FROM final_delivery_billing WHERE invoice_status='sent' AND payment_status='cleared' AND delivery_status='ready' ORDER BY cleared_at ASC");billing_json(200,['items'=>$s->fetchAll(PDO::FETCH_ASSOC)]);}
 if(preg_match('/^n8n-claim-(\d+)$/',$action,$m)&&$method==='POST'){$id=(int)$m[1];try{$db->beginTransaction();$s=$db->prepare("SELECT * FROM final_delivery_billing WHERE id=? AND invoice_status='sent' AND payment_status='cleared' AND delivery_status='ready' FOR UPDATE");$s->execute([$id]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!$row){$db->rollBack();billing_json(409,['error'=>'Record is not eligible; invoice and payment clearance are required.']);}$claim=bin2hex(random_bytes(18));$u=$db->prepare("UPDATE final_delivery_billing SET delivery_status='processing',delivery_claim_token=?,delivery_claimed_at=UTC_TIMESTAMP(3),delivery_error=NULL WHERE id=?");$u->execute([$claim,$id]);$db->commit();$row['delivery_status']='processing';$row['delivery_claim_token']=$claim;billing_json(200,['item'=>$row]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
 if(preg_match('/^n8n-complete-(\d+)$/',$action,$m)&&$method==='POST'){$id=(int)$m[1];$b=billing_body();$claim=(string)($b['claim_token']??'');$status=(string)($b['status']??'');$link=isset($b['final_link'])?trim((string)$b['final_link']):null;$error=isset($b['error'])?substr((string)$b['error'],0,1000):null;if($claim===''||!in_array($status,['delivered','failed'],true)||($status==='delivered'&&(!is_string($link)||!filter_var($link,FILTER_VALIDATE_URL)||!str_starts_with($link,'https://')))billing_json(400,['error'=>'Invalid delivery result.']);$s=$db->prepare("UPDATE final_delivery_billing SET delivery_status=?,final_link=?,delivered_at=IF(?='delivered',UTC_TIMESTAMP(3),delivered_at),delivery_error=?,delivery_claim_token=NULL WHERE id=? AND delivery_claim_token=? AND payment_status='cleared'");$s->execute([$status,$link,$status,$error,$id,$claim]);if($s->rowCount()!==1)billing_json(409,['error'=>'Claim is stale or payment is not cleared.']);billing_audit($db,$id,'n8n',$status==='delivered'?'delivered':'delivery_failed',['delivery_status'=>$status]);billing_json(200,['ok'=>true]);}
 billing_json(404,['error'=>'Unknown n8n action.']);
}
$username=billing_admin();
if($action==='billing'&&$method==='GET'){$db=billing_pdo();$s=$db->query('SELECT id,task_code,phone,customer_name,project_name,task_type,folder_id,drive_file_id,file_name,mime_type,file_size,bill_amount,invoice_number,invoice_file_url,invoice_status,payment_status,payment_reference,cleared_by,cleared_at,delivery_status,final_link,delivered_at,created_at FROM final_delivery_billing ORDER BY created_at DESC');billing_json(200,['items'=>$s->fetchAll(PDO::FETCH_ASSOC)]);}
if(preg_match('/^invoice-(\d+)$/',$action,$m)&&$method==='POST'){billing_csrf();$db=billing_pdo();$id=(int)$m[1];$b=billing_body();$amount=filter_var($b['bill_amount']??null,FILTER_VALIDATE_FLOAT);$number=trim((string)($b['invoice_number']??''));$url=trim((string)($b['invoice_file_url']??''));if($amount===false||$amount<=0||$amount>100000000||$number===''||strlen($number)>100)billing_json(400,['error'=>'Enter a valid amount and invoice number.']);if($url!==''&&(!filter_var($url,FILTER_VALIDATE_URL)||!str_starts_with($url,'https://')||strlen($url)>2000))billing_json(400,['error'=>'Invoice reference must be an HTTPS URL.']);$s=$db->prepare("UPDATE final_delivery_billing SET bill_amount=?,invoice_number=?,invoice_file_url=?,invoice_status='sent' WHERE id=? AND invoice_status='pending' AND payment_status='unpaid'");$s->execute([$amount,$number,$url!==''?$url:null,$id]);if($s->rowCount()!==1)billing_json(409,['error'=>'Invoice cannot be updated for this record.']);billing_audit($db,$id,$username,'invoice_sent',['invoice_number'=>$number,'bill_amount'=>$amount]);billing_json(200,['ok'=>true]);}
if(preg_match('/^clear-(\d+)$/',$action,$m)&&$method==='POST'){billing_csrf();$db=billing_pdo();$id=(int)$m[1];$b=billing_body();$ref=trim((string)($b['payment_reference']??''));if($ref===''||strlen($ref)>255)billing_json(400,['error'=>'Enter a payment reference before clearing.']);$s=$db->prepare("UPDATE final_delivery_billing SET payment_status='cleared',payment_reference=?,cleared_by=?,cleared_at=UTC_TIMESTAMP(3),delivery_status='ready' WHERE id=? AND invoice_status='sent' AND payment_status='unpaid'");$s->execute([$ref,$username,$id]);if($s->rowCount()!==1)billing_json(409,['error'=>'Send an invoice before recording cleared payment.']);billing_audit($db,$id,$username,'payment_cleared',['payment_reference'=>$ref]);billing_json(200,['ok'=>true,'message'=>'Payment cleared. The separately authenticated n8n workflow may now process delivery.']);}
billing_json(404,['error'=>'Unknown action.']);
